class Solution {
public:
    vector<vector<bool>> row(10,vector<bool>(10,false)), col(10,vector<bool>(10,false));
    void solve(vector<vector<char>>& board, int r, int c)
    {
        if(r==9)
            return;
        for(int i=0;i<9;i++)
        {
            if(board[r][i]=='.')
            {
                for(int j=1;j<9;j++)
                {
                    if(col[i][j]==false && row[r][j]==false)
                    {
                        board[r][i]=j;
                        solve(board,r+1,c);
                    }
                }
            }
        }
        return;
    }
    void solveSudoku(vector<vector<char>>& board) {
        for(int i=0;i<9;i++)
        {
            for(int j=0;j<9;j++)
            {
                int x = board[i][j]-'0';
                row[i][x] = true;
                col[j][x] = true;
            }
        }
        solve(board,0,0);
    }
};
